def method_call_camel_case?(node)
  @method_call_parentheses_state[:method_call_camel_case] = node&.type
  return false unless node
  name = node.respond_to?(:method_name) ? node.method_name.to_s : ''
  name.match?(/\A[A-Z]/)
end

def method_call_predicate?(node)
  @method_call_parentheses_state[:method_call_predicate] = node&.type
  return false unless node
  name = node.respond_to?(:method_name) ? node.method_name.to_s : ''
  name.end_with?('?')
end

def method_call_bang?(node)
  @method_call_parentheses_state[:method_call_bang] = node&.type
  return false unless node

